from __future__ import annotations

import ast
from pathlib import Path

from lokdocsqr.core.models import ActionLog, ActionProposal, NodeResult, NodeState, Risk

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src" / "lokdocsqr"

# ActionProposal is deprecated (8z). Only core/** may still import it
# (policy layer, planning, preview, executor, models). Nodes/gui/tools
# must NOT grow new dependencies on the deprecated type.
_ALLOWED_TOP_PREFIXES = ("core/",)


def _allowlisted(rel: str) -> bool:
    return any(rel.startswith(p) for p in _ALLOWED_TOP_PREFIXES)


def test_action_proposal_marked_deprecated() -> None:
    assert ActionProposal.__deprecated__ is True


def test_action_proposal_from_node_result() -> None:
    nr = NodeResult(
        node_id="n1",
        state=NodeState.ENABLED,
        outputs={"path": "out.txt"},
        payload={"path": "payload.txt"},
    )
    proposal = ActionProposal.from_node_result(nr)
    assert proposal.node_id == "n1"
    assert proposal.operation == "unknown"
    assert proposal.target_paths == ()
    assert proposal.payload == {"path": "payload.txt"}
    assert "enabled" in proposal.summary

    nr_no_payload = NodeResult(
        node_id="n2",
        state=NodeState.ENABLED,
        outputs={"a": 1},
    )
    proposal2 = ActionProposal.from_node_result(nr_no_payload)
    assert proposal2.payload == {"a": 1}


def test_action_proposal_to_action_log_roundtrip() -> None:
    proposal = ActionProposal(
        node_id="n1",
        operation="write",
        target_paths=("a.txt",),
        payload={"x": 1},
        summary="write a.txt",
        confidence=0.7,
        risk=Risk.MEDIUM,
        source=Path("src.txt"),
    )
    log = proposal.to_action_log(
        dry_run=True,
        status="planned",
        rollback_eligible=True,
    )
    assert isinstance(log, ActionLog)
    assert log.action_type == "write"
    assert log.node_id == "n1"
    assert log.target == "a.txt"
    assert log.source == "src.txt"
    assert log.dry_run is True
    assert log.status == "planned"
    assert log.rollback_eligible is True
    assert log.extra["proposal"]["target_paths"] == ["a.txt"]


def test_no_new_action_proposal_imports() -> None:
    violations: list[str] = []
    for path in sorted(SRC.rglob("*.py")):
        rel = path.relative_to(SRC).as_posix()
        if _allowlisted(rel):
            continue
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                if any(alias.name == "ActionProposal" for alias in node.names):
                    violations.append(f"{rel}:{node.lineno} imports ActionProposal")
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name.endswith("ActionProposal"):
                        violations.append(f"{rel}:{node.lineno} imports ActionProposal")
    assert not violations, "ActionProposal import violations:\n" + "\n".join(violations)
